/* White Parrot 57 by Alaner-xs — https://uiverse.io/Alaner-xs/white-parrot-57 */
.container input {
 position: absolute;
 opacity: 0;
 cursor: pointer;
 height: 0;
 width: 0;
}

.container {
 display: block;
 position: relative;
 cursor: pointer;
 font-size: 20px;
 user-select: none;
}

.checkmark {
 position: relative;
 top: 0;
 left: 0;
 height: 1.3em;
 width: 1.3em;
 background-color: #ccc;
 border-bottom-left-radius: 15px;
 border-top-right-radius: 15px;
 box-shadow: 0px 0px 17px #c7bbb8;
}

.container input:checked ~ .checkmark {
 background-color: #f34b21;
 box-shadow: 0px 0px 17px #f34b21;
}

.checkmark:after {
 content: "";
 position: absolute;
 display: none;
}

.container input:checked ~ .checkmark:after {
 display: block;
}

.container .checkmark:after {
 left: 0.45em;
 top: 0.25em;
 width: 0.25em;
 height: 0.5em;
 border: solid rgb(233, 222, 222);
 border-width: 0 0.15em 0.15em 0;
 transform: rotate(45deg);
}
